import { FEATURE_DETAILS, FEATS, SPELLS } from "./mechanics-pl.js";

Object.assign(FEATURE_DETAILS, {
  "Ability Score Increase": "Premie do cech wynikające z pochodzenia są już uwzględnione w wartościach widocznych na karcie. Nie dodajesz ich ponownie podczas gry.",
  "Agile Parry": "Jeśli w swojej turze wykonasz atak bez broni jako część Akcji Ataku i trzymasz broń swojej szkoły walki, otrzymujesz +2 do KP do początku swojej następnej tury, o ile broń pozostaje w twojej ręce i nie jesteś obezwładniony.",
  "Amorphous": "Możesz przeciskać się przez szczeliny szerokie na 1 cal bez dodatkowego kosztu ruchu. Masz także przewagę w testach wykonywanych, aby rozpocząć lub zakończyć pochwycenie.",
  "Ancestral Legacy": "Zachowujesz wskazane na karcie biegłości odziedziczone po wcześniejszym pochodzeniu. Ich premie są już uwzględnione w tabeli umiejętności.",
  "Arcane Armor": "Twój pancerz jest zintegrowany z ciałem lub kostiumem. Ignorujesz wymagania Siły pancerza, możesz używać go jako skupienia dla swoich mocy, a jego elementów nie można zdjąć wbrew twojej woli. Założenie albo zdjęcie pancerza możesz przeprowadzić jako akcję, jeśli masz przy sobie odpowiednie narzędzia.",
  "Arcane Firearm": "Wybrane urządzenie działa jako wzmacniacz mocy. Gdy używasz przez nie mocy Wynalazcy zadającej obrażenia, rzucasz dodatkową k8 i dodajesz wynik do jednego rzutu obrażeń tej mocy.",
  "Armor Model": "Po krótkim albo długim odpoczynku możesz wybrać jeden z dwóch trybów pancerza: Strażnik lub Infiltrator. Każdy tryb daje własną broń specjalną i dodatkową cechę opisaną osobno na karcie. Zmiana trybu nie zużywa komórki mocy.",
  "Armorer Spells": "Moce specjalizacji są zawsze przygotowane i nie liczą się do normalnego limitu przygotowanych mocy. Na tym poziomie obejmują Pociski energii, Falę uderzeniową, Astralne odbicia i Roztrzaskanie.",
  "Artillerist Spells": "Moce specjalizacji są zawsze przygotowane i nie liczą się do normalnego limitu przygotowanych mocy. Na tym poziomie obejmują Mistyczną tarczę, Falę uderzeniową, Palące promienie i Roztrzaskanie.",
  "Assassinate": "Masz przewagę w rzutach ataku przeciw stworzeniom, które jeszcze nie wykonały swojej pierwszej tury w tej walce. Każde twoje trafienie przeciw stworzeniu zaskoczonemu jest trafieniem krytycznym.",
  "Astral Knowledge": "Po zakończeniu długiego odpoczynku wybierasz jedną umiejętność albo jeden zestaw narzędzi. Do następnego długiego odpoczynku masz w nim biegłość. Wybór możesz zmieniać po każdym długim odpoczynku.",
  "Bonus Cantrip": "Otrzymujesz dodatkową sztuczkę wskazaną na karcie. Nie liczy się ona do normalnego limitu znanych sztuczek tej klasy.",
  "Bonus Proficiencies": "Otrzymujesz wskazane na karcie dodatkowe biegłości. Są stale aktywne i nie wymagają żadnej akcji ani wydawania zasobu.",
  "Cat's Claws": "Masz szybkość wspinaczki równą normalnej szybkości poruszania się. Twoje naturalne pazury mogą służyć jako atak bez broni, zadający 1k6 + modyfikator Siły obrażeń ciętych przy trafieniu.",
  "Cat's Talent": "Masz biegłość w Czujności i Infiltracji. Premia z biegłości jest już uwzględniona w wartościach widocznych na karcie.",
  "Changeling Instincts": "Masz biegłość w dwóch wskazanych na karcie umiejętnościach społecznych. Premia z biegłości jest już uwzględniona w ich wartościach.",
  "Channel Divinity: Abjure Enemy": "Jako akcję wybierasz jedno stworzenie w odległości do 60 stóp, które widzisz. Cel wykonuje rzut obronny na Mądrość. Przy porażce jest przerażony przez 1 minutę albo do chwili otrzymania obrażeń. Dopóki jest przerażony, jego szybkość wynosi 0. Istoty piekielne i nieumarłe mają utrudnienie w tym rzucie.",
  "Channel Divinity: Inspiring Smite": "Bezpośrednio po użyciu potężnego uderzenia możesz użyć akcji dodatkowej i rzucić 2k8 + 5. Rozdzielasz wynik jako tymczasowe punkty wytrzymałości pomiędzy wybrane stworzenia w odległości do 30 stóp, w tym siebie. Jedno stworzenie nie może otrzymać więcej tymczasowych punktów niż uzyskany wynik.",
  "Channel Divinity: Peerless Athlete": "Jako akcję dodatkową uruchamiasz ten efekt na 10 minut. Przez ten czas masz przewagę w testach Sprawności i Akrobatyki, możesz pchać, ciągnąć i podnosić dwa razy większy ciężar, a długość twoich skoków w dal i wzwyż zwiększa się o 10 stóp.",
  "Channel Divinity: Vow of Enmity": "Jako akcję dodatkową wybierasz stworzenie w odległości do 10 stóp. Przez 1 minutę masz przewagę we wszystkich rzutach ataku przeciw temu stworzeniu. Efekt kończy się wcześniej, jeśli cel spadnie do 0 punktów wytrzymałości albo straci przytomność.",
  "Circle Spells": "Moce przypisane do kręgu są zawsze przygotowane i nie liczą się do normalnego limitu przygotowanych mocy. Konkretna lista jest podana na karcie postaci.",
  "Commander's Strike": "Gdy wykonujesz Akcję Ataku, możesz zrezygnować z jednego własnego ataku i użyć akcji dodatkowej, wydając jedną kość manewru. Wybierasz sojusznika, który cię widzi lub słyszy. Może on natychmiast użyć reakcji, aby wykonać jeden atak bronią i dodać wynik kości manewru do obrażeń przy trafieniu.",
  "Deathless Nature": "Nie musisz oddychać, jeść ani pić. Nie musisz spać, a magia nie może cię uśpić. Długi odpoczynek możesz ukończyć pozostając nieruchomo i świadomie przez odpowiedni czas wskazany przez zasady postaci.",
  "Disarming Attack": "Gdy trafisz atakiem bronią, możesz wydać jedną kość manewru i dodać jej wynik do obrażeń. Cel wykonuje rzut obronny na Siłę przeciw ST 14. Przy porażce upuszcza jeden trzymany przez siebie przedmiot, który ląduje u jego stóp.",
  "Divine Magic": "Możesz wybierać część swoich znanych mocy również z listy kapłana. Jeśli karta wskazuje konkretną dodatkową moc, jest ona już uwzględniona w sekcji Moce aktywne i liczy się zgodnie z opisem tej cechy.",
  "Druid Circle": "Twój krąg określa specjalizację druida. Daje dodatkowe moce i cechy opisane osobno w sekcji Specjalizacja. Moce kręgu są zawsze przygotowane i nie liczą się do zwykłego limitu przygotowanych mocy.",
  "Druidic": "Znasz tajny język druidów. Możesz nim zostawiać ukryte wiadomości. Osoba znająca ten język zauważa taką wiadomość automatycznie, a pozostali mogą wykryć jej obecność przy odpowiednio trudnym teście, ale nie odczytają treści bez odpowiedniej zdolności.",
  "Duergar Magic": "Masz wrodzone moce krasnoludów szarych wskazane na karcie. Każdej mocy ograniczonej odpoczynkiem możesz użyć raz bez wydawania komórki, a użycie odzyskujesz po długim odpoczynku.",
  "Duergar Resilience": "Masz przewagę w rzutach obronnych przeciw zauroczeniu i ogłuszeniu.",
  "Eerie Token": "Możesz odłamać niewielki fragment siebie i przekazać go innej osobie. Dopóki fragment istnieje, możesz używać go do wybranych efektów swojej cechy pochodzenia, takich jak przekazywanie krótkiej wiadomości lub obserwowanie otoczenia, zgodnie z ograniczeniami opisanymi na karcie.",
  "Eldritch Cannon": "Jako akcję możesz stworzyć małe lub malutkie działo w wolnym miejscu do 5 stóp. Wybierasz jego tryb przy tworzeniu. Działo ma własne KP i punkty wytrzymałości. W każdej swojej turze możesz akcją dodatkową aktywować jego efekt, jeśli znajduje się do 60 stóp. Działo działa przez 1 godzinę albo do zniszczenia. Pierwsze stworzenie po długim odpoczynku nie wymaga komórki mocy; kolejne wymaga komórki 1. poziomu lub wyższej.",
  "Eldritch Invocation: Agonizing Blast": "Gdy trafisz promieniem Pocisku energii, dodajesz swój modyfikator Charyzmy do obrażeń tego promienia. Jeśli tworzysz kilka promieni, premię dodajesz osobno do każdego trafionego promienia.",
  "Eldritch Invocation: Mask of Many Faces": "Możesz używać Zmiany wyglądu dowolną liczbę razy bez wydawania komórki mocy.",
  "Eldritch Invocation: Misty Visions": "Możesz używać Cichego obrazu dowolną liczbę razy bez wydawania komórki mocy. Efekt wymaga koncentracji i może trwać do 10 minut.",
  "Eldritch Invocations": "Znasz wskazaną na karcie liczbę trwałych ulepszeń swoich mocy. Każde działa zgodnie z własnym opisem i nie zużywa komórki mocy, chyba że opis wyraźnie stanowi inaczej.",
  "Expanded Spell List": "Twoja specjalizacja dodaje nowe moce do listy, z której możesz wybierać znane moce Czarnoksiężnika. Samo dodanie do listy nie oznacza automatycznego poznania wszystkich tych mocy, chyba że karta wyraźnie mówi inaczej.",
  "Fey": "Na potrzeby efektów zależnych od typu stworzenia jesteś traktowany jako istota baśniowa, a nie humanoid. Może to zmieniać działanie niektórych mocy, które celują wyłącznie w humanoidów.",
  "Fey Presence": "Jako akcję tworzysz krótką falę nadnaturalnego wpływu w sześcianie o boku 10 stóp wychodzącym od ciebie. Wybrane stworzenia w obszarze wykonują rzut obronny na Mądrość. Przy porażce każde z nich jest zauroczone albo przerażone, według twojego wyboru, do końca twojej następnej tury. Odzyskujesz zdolność po krótkim lub długim odpoczynku.",
  "Fairy Magic": "Znasz Drobny przejaw natury. Od odpowiednich poziomów możesz raz na długi odpoczynek użyć Świetlistej aury oraz Zwiększenia/Zmniejszenia bez wydawania komórki. Jeśli masz własne komórki mocy, możesz również używać ich normalnie.",
  "Favored Enemy": "Wybierasz określony rodzaj przeciwników. Masz przewagę w testach Operacji terenowych wykonywanych w celu ich tropienia oraz w testach Inteligencji służących przypominaniu sobie informacji o nich. Zyskujesz także język powiązany z wybranym przeciwnikiem, jeśli karta tak wskazuje.",
  "Favored by the Gods": "Gdy nie zdasz rzutu obronnego albo spudłujesz rzutem ataku, możesz rzucić 2k4 i dodać wynik do rzutu, potencjalnie zmieniając porażkę w sukces. Po użyciu odzyskujesz zdolność po krótkim lub długim odpoczynku.",
  "Feline Agility": "Gdy zaczynasz poruszać się w swojej turze, możesz podwoić swoją szybkość do końca tej tury. Po użyciu nie możesz zrobić tego ponownie, dopóki nie zakończysz jednej ze swoich tur bez wykorzystania żadnego ruchu.",
  "Fire Resistance": "Masz odporność na obrażenia od ognia, więc po zastosowaniu pozostałych modyfikatorów otrzymujesz połowę takich obrażeń.",
  "Flight": "Masz szybkość lotu równą swojej normalnej szybkości, o ile nie nosisz średniego ani ciężkiego pancerza. Lot wykorzystuje zwykły limit ruchu w turze.",
  "Flurry of Blows": "Bezpośrednio po wykonaniu Akcji Ataku możesz wydać 1 punkt skupienia i użyć akcji dodatkowej, aby wykonać dwa ataki bez broni zamiast jednego.",
  "Form of the Beast": "Gdy rozpoczynasz szał, wybierasz jedną naturalną broń swojej bestialskiej formy. Wybrana broń działa przez czas trwania szału i korzysta z zasad opisanych przy danym wariancie na karcie.",
  "Fury of the Small": "Gdy trafisz stworzenie większe od siebie i zadasz mu obrażenia, możesz zwiększyć te obrażenia o +3. Możesz użyć tej cechy tylko raz na turę i masz 3 użycia na długi odpoczynek.",
  "Giant Power": "Twoja więź z mocą olbrzymów daje dodatkową zdolność opisaną na karcie. Korzysta ona z twoich normalnych zasad klasy i nie wymaga dodatkowego zasobu, chyba że jej opis mówi inaczej.",
  "Giant's Havoc": "Podczas szału możesz zwiększyć swój rozmiar do Dużego, jeśli masz miejsce. Twój zasięg ataków wręcz zwiększa się o 5 stóp, a raz w każdej swojej turze przy trafieniu bronią lub rzutem dodajesz dodatkowe obrażenia wynikające z tej cechy. Efekt trwa do końca szału.",
  "Githyanki Psionics": "Znasz Astralną dłoń. Możesz także raz na długi odpoczynek użyć Skoku oraz Krótkiego portalu bez wydawania komórki mocy. Jeśli masz własne komórki, możesz używać tych mocy również normalnie.",
  "Githzerai Psionics": "Znasz Astralną dłoń. Możesz raz na długi odpoczynek użyć Mistycznej tarczy i Wykrycia myśli bez wydawania komórki mocy. Jeśli masz własne komórki, możesz używać tych mocy również normalnie.",
  "Grappling Strike": "Natychmiast po trafieniu stworzenia atakiem wręcz możesz wydać jedną kość manewru i użyć akcji dodatkowej, aby spróbować je pochwycić. Do testu Sprawności wykonywanego w tej próbie dodajesz wynik kości manewru.",
  "Guardian: Defensive Field": "Jako akcję dodatkową otrzymujesz 5 tymczasowych punktów wytrzymałości. Masz 3 użycia tej zdolności i odzyskujesz wszystkie po długim odpoczynku.",
  "Guardian: Thunder Gauntlets": "Rękawice pancerza stają się bronią, z którą masz biegłość. Przy trafieniu zadają 1k8 + modyfikator Inteligencji obrażeń od grzmotu. Trafione stworzenie ma utrudnienie w rzutach ataku przeciw wszystkim celom innym niż ty do początku twojej następnej tury.",
  "Hare-Trigger": "Dodajesz premię z biegłości do inicjatywy. Na 5. poziomie oznacza to dodatkowe +3, oprócz modyfikatora Zręczności.",
  "Hex Magic": "Możesz raz na długi odpoczynek użyć Piętna oraz Zmiany wyglądu bez wydawania komórki mocy. Jeśli masz własne komórki, możesz również korzystać z nich normalnie.",
  "Hidden Step": "Jako akcję dodatkową stajesz się niewidzialny do początku swojej następnej tury. Efekt kończy się wcześniej, jeśli wykonasz rzut ataku, zadasz obrażenia albo zmusisz stworzenie do wykonania rzutu obronnego. Odzyskujesz zdolność po krótkim lub długim odpoczynku.",
  "Hold Breath": "Możesz wstrzymać oddech przez maksymalnie 1 godzinę. Nie wymaga to żadnej akcji ani testu, o ile nic szczególnego nie skraca tego czasu.",
  "Hunter's Sense": "Jako akcję wybierasz stworzenie, które widzisz w odległości do 60 stóp. Poznajesz jego odporności, niewrażliwości i podatności na typy obrażeń. Efekt nie ujawnia cech ukrytych przez magię blokującą wróżenie. Masz 2 użycia na długi odpoczynek.",
  "Infiltrator: Dampening Field": "Masz przewagę w testach Infiltracji. Jeśli twój pancerz normalnie dawałby utrudnienie w takich testach, przewaga i utrudnienie znoszą się, więc wykonujesz zwykły rzut.",
  "Infiltrator: Lightning Launcher": "Pancerz ma wbudowane działo elektryczne o zasięgu 90/300 stóp. Używasz Inteligencji do rzutu ataku i obrażeń. Trafienie zadaje 1k6 + modyfikator Inteligencji obrażeń od elektryczności, a raz w każdej swojej turze możesz dodać dodatkowe 1k6 obrażeń jednemu trafionemu celowi.",
  "Infiltrator: Powered Steps": "Twoja normalna szybkość poruszania się zwiększa się o 5 stóp. Premia jest już uwzględniona w wartości Szybkości na karcie.",
  "Infusion: Enhanced Arcane Focus": "Wybrany różdżka, laska albo inny skupiający przedmiot daje +1 do rzutów ataku mocą i pozwala ignorować połowiczną osłonę przy dystansowych atakach mocą. Premia działa tylko wtedy, gdy faktycznie używasz ulepszonego przedmiotu jako skupienia.",
  "Infusion: Enhanced Defense": "Wybrany pancerz albo tarcza otrzymuje +1 do KP. Jeśli karta oznacza ulepszenie jako aktywne, premia jest już uwzględniona w wartości KP.",
  "Infusion: Homunculus Servant": "Tworzysz małego mechanicznego pomocnika o własnych statystykach. W swojej turze porusza się samodzielnie, ale domyślnie wykonuje tylko Unik. Możesz akcją dodatkową wydać mu polecenie wykonania innej akcji z jego statystyk. Jeśli jesteś obezwładniony, pomocnik może działać samodzielnie według prowadzącego.",
  "Infusion: Mind Sharpener": "Ulepszony pancerz albo szata ma 4 ładunki. Gdy nie zdasz rzutu obronnego na Kondycję wykonywanego w celu utrzymania koncentracji, możesz użyć reakcji i wydać 1 ładunek, aby zamiast tego uznać rzut za udany. Każdego dnia o świcie odzyskujesz 1k4 zużytych ładunków.",
  "Infusion: Replicate Magic Item: Bag of Holding": "Tworzysz kieszeń wymiarową mieszczącą do 500 funtów i 64 stóp sześciennych zawartości. Sama waży 15 funtów niezależnie od zawartości. Jeśli zostanie przebita lub rozdarta, zostaje zniszczona, a jej zawartość trafia do Planu Astralnego.",
  "Kensei Weapons": "Wybierasz określone bronie swojej szkoły. Traktujesz je jako broń mnicha, więc możesz używać z nimi cech Sztuk walki i innych zdolności, które wymagają broni mnicha. Wybrane bronie są podane na karcie.",
  "Kensei's Shot": "Jako akcję dodatkową wzmacniasz swoją broń dystansową szkoły do końca bieżącej tury. Każdy trafiony nią atak dystansowy w tej turze zadaje dodatkowe 1k4 obrażeń tego samego typu co broń.",
  "Knowledge from a Past Life": "Po wykonaniu testu cechy możesz rzucić k6 i dodać wynik do testu. Możesz zrobić to po zobaczeniu wyniku k20, ale zanim prowadzący rozstrzygnie konsekwencje. Masz 3 użycia i odzyskujesz wszystkie po długim odpoczynku.",
  "Leporine Senses": "Masz biegłość w Czujności. Premia z biegłości jest już uwzględniona w wartości tej umiejętności na karcie.",
  "Lightning Resistance": "Masz odporność na obrażenia od elektryczności, więc po zastosowaniu pozostałych modyfikatorów otrzymujesz połowę takich obrażeń.",
  "Little Giant": "Przy ustalaniu udźwigu oraz masy, którą możesz pchać, ciągnąć lub podnosić, liczysz się jako stworzenie o jeden rozmiar większe.",
  "Lucky Footwork": "Gdy nie zdasz rzutu obronnego na Zręczność, możesz użyć reakcji i rzucić k4, dodając wynik do rzutu obronnego. Możesz zmienić porażkę w sukces. Nie możesz użyć tej cechy, jeśli jesteś powalony albo twoja szybkość wynosi 0.",
  "Mental Discipline": "Masz przewagę w rzutach obronnych przeciw zauroczeniu i przerażeniu.",
  "Menacing": "Masz biegłość w Presji. Premia z biegłości jest już uwzględniona w wartości tej umiejętności na karcie.",
  "Menacing Attack": "Gdy trafisz atakiem bronią, możesz wydać jedną kość manewru i dodać jej wynik do obrażeń. Cel wykonuje rzut obronny na Mądrość przeciw ST 14. Przy porażce jest przerażony tobą do końca twojej następnej tury.",
  "Metamagic: Careful Spell": "Koszt: 1 punkt magii. Gdy używasz mocy zmuszającej inne stworzenia do rzutu obronnego, możesz wybrać liczbę stworzeń nie większą niż twój modyfikator Charyzmy. Wybrane stworzenia automatycznie zdają pierwszy rzut obronny przeciw tej mocy.",
  "Metamagic: Distant Spell": "Koszt: 1 punkt magii. Jeśli moc ma zasięg co najmniej 5 stóp, podwajasz jej zasięg. Jeśli ma zasięg dotyku, jej zasięg staje się 30 stóp.",
  "Metamagic: Empowered Spell": "Koszt: 1 punkt magii. Po rzucie obrażeń możesz przerzucić liczbę kości obrażeń nie większą niż twój modyfikator Charyzmy, minimum jedną. Musisz użyć nowych wyników. Tę odmianę metamagii można łączyć z inną metamagiczną modyfikacją tej samej mocy.",
  "Metamagic: Heightened Spell": "Koszt: 3 punkty magii. Jedno stworzenie będące celem mocy ma utrudnienie w pierwszym rzucie obronnym przeciw tej mocy.",
  "Metamagic: Quickened Spell": "Koszt: 2 punkty magii. Moc, której normalny czas użycia wynosi 1 akcję, używasz jako akcję dodatkową. Nadal obowiązują ograniczenia dotyczące używania innych mocy w tej samej turze.",
  "Metamagic: Subtle Spell": "Koszt: 1 punkt magii. Używasz mocy bez gestów i słów. Jeśli moc wymaga kosztownego lub zużywanego komponentu materialnego, ten komponent nadal jest potrzebny.",
  "Metamagic: Transmuted Spell": "Koszt: 1 punkt magii. Gdy moc zadaje obrażenia od kwasu, zimna, ognia, elektryczności, trucizny albo grzmotu, możesz zmienić ten typ obrażeń na inny z tej listy.",
  "Metamagic: Twinned Spell": "Gdy używasz mocy, która normalnie celuje tylko w jedno stworzenie i nie ma zasięgu na samego siebie, możesz wydać liczbę punktów magii równą poziomowi mocy, minimum 1. Wybierasz drugie stworzenie w zasięgu i ta sama moc obejmuje również je.",
  "Mingle with the Wind": "Znasz elektryczny dotyk. Od odpowiedniego poziomu możesz raz na długi odpoczynek użyć Łagodnego opadania oraz Lewitacji bez wydawania komórki mocy. Jeśli masz własne komórki, możesz korzystać z tych mocy również normalnie.",
  "Monster Slayer Magic": "Otrzymujesz dodatkowe moce specjalizacji. Są zawsze znane i nie liczą się do zwykłego limitu znanych mocy Łowcy. Konkretne moce dostępne na tym poziomie są podane na karcie.",
  "Mountain Born": "Masz odporność na obrażenia od zimna i jesteś naturalnie przystosowany do dużych wysokości, również powyżej 20 000 stóp.",
  "Natural Explorer": "W wybranym typie terenu twoja grupa podróżuje sprawniej. Trudny teren nie spowalnia podróży, nie gubicie się inaczej niż wskutek magii, a podczas wykonywania innych czynności pozostajesz czujny na zagrożenia. Gdy podróżujesz sam, możesz poruszać się skrycie w normalnym tempie. Łatwiej znajdujesz pożywienie i dokładniej odczytujesz ślady.",
  "Natural Recovery": "Raz na dzień po zakończeniu krótkiego odpoczynku możesz odzyskać zużyte komórki mocy o łącznym poziomie nie większym niż 3. Żadna odzyskana komórka nie może być wyższa niż 5. poziom.",
  "Natural Resilience": "Masz przewagę w rzutach obronnych przeciw zatruciu oraz odporność na obrażenia od kwasu i trucizny.",
  "Nimble Escape": "W każdej swojej turze możesz użyć akcji dodatkowej, aby wykonać Odskok albo Ukrycie.",
  "Oath Spells": "Moce przysięgi są zawsze przygotowane i nie liczą się do normalnego limitu przygotowanych mocy. Konkretna lista dla tej postaci jest podana na karcie.",
  "Open Hand Technique": "Za każdym razem, gdy trafisz stworzenie jednym z ataków wykonanych w ramach Gradu Ciosów, możesz nałożyć na nie jeden efekt: przewrócić je po nieudanym rzucie obronnym na Zręczność, odepchnąć do 15 stóp po nieudanym rzucie obronnym na Siłę albo pozbawić je możliwości wykonywania reakcji do końca twojej następnej tury.",
  "Otherworldly Patron": "Źródło twojej mocy określa specjalizację Czarnoksiężnika. Wszystkie konkretne zdolności wynikające z tego źródła są opisane osobno w sekcji Specjalizacja.",
  "Otherworldly Patron: Hexblade": "Źródłem tej mechaniki jest więź z zaklętym orężem lub nadnaturalną energią. Wszystkie konkretne zdolności, w tym przekleństwo i używanie Charyzmy do walki, są opisane osobno w sekcji Specjalizacja.",
  "Pact Boon": "Otrzymujesz specjalny dar źródła mocy. Konkretna forma daru i wszystkie wynikające z niej możliwości są opisane na karcie. Jeśli dar zapewnia dodatkowe sztuczki lub przedmiot, nie liczą się one do zwykłych limitów, chyba że opis mówi inaczej.",
  "Patient Defense": "Wydajesz 1 punkt skupienia i jako akcję dodatkową wykonujesz Unik. Do początku swojej następnej tury ataki przeciw tobie mają utrudnienie, jeśli widzisz napastnika, a ty masz przewagę w rzutach obronnych na Zręczność.",
  "Powerful Build": "Przy ustalaniu udźwigu oraz masy, którą możesz pchać, ciągnąć lub podnosić, liczysz się jako stworzenie o jeden rozmiar większe.",
  "Primal Path": "Wybrana ścieżka określa specjalizację Barbarzyńcy. Wszystkie konkretne zdolności tej ścieżki są opisane osobno w sekcji Specjalizacja.",
  "Primeval Awareness": "Możesz wydać jedną komórkę mocy Łowcy i przez 1 minutę za każdy poziom komórki wyczuwać, czy w promieniu kilku mil znajdują się określone typy istot nadnaturalnych. Zdolność nie ujawnia ich liczby ani dokładnej lokalizacji.",
  "Psionic Fortitude": "Masz przewagę w rzutach obronnych przeciw zauroczeniu i ogłuszeniu. Zdolność działa stale i nie wymaga akcji ani zasobu.",
  "Psionic Spells": "Otrzymujesz dodatkowe moce psioniczne specjalizacji. Są zawsze znane i nie liczą się do normalnego limitu znanych mocy Zaklinacza. Konkretna lista jest uwzględniona w sekcji Moce aktywne.",
  "Psychic Resilience": "Masz odporność na obrażenia psychiczne, więc po zastosowaniu pozostałych modyfikatorów otrzymujesz połowę takich obrażeń.",
  "Pushing Attack": "Gdy trafisz atakiem bronią, możesz wydać jedną kość manewru i dodać jej wynik do obrażeń. Jeśli cel jest Duży lub mniejszy, wykonuje rzut obronny na Siłę przeciw ST 14. Przy porażce możesz odepchnąć go od siebie o maksymalnie 15 stóp.",
  "Rabbit Hop": "Jako akcję dodatkową możesz skoczyć o liczbę stóp równą pięciokrotności premii z biegłości, bez prowokowania ataków okazyjnych. Możesz użyć tej zdolności tylko wtedy, gdy twoja szybkość jest większa od 0. Masz 3 użycia na długi odpoczynek.",
  "Ranger Archetype": "Wybrana specjalizacja określa dodatkowe zdolności Łowcy. Wszystkie konkretne efekty są opisane osobno w sekcji Specjalizacja.",
  "Reach to the Blaze": "Znasz Płomień w dłoni. Możesz raz na długi odpoczynek użyć Płonących dłoni, a od 5. poziomu również Ognistego ostrza, bez wydawania komórki mocy. Jeśli masz własne komórki, możesz używać tych mocy również normalnie.",
  "Relentless Endurance": "Gdy obrażenia sprowadziłyby cię do 0 punktów wytrzymałości, ale nie zabiły natychmiast, możesz zamiast tego pozostać na 1 punkcie wytrzymałości. Po użyciu odzyskujesz zdolność po długim odpoczynku.",
  "Riposte": "Gdy stworzenie spudłuje atakiem wręcz przeciw tobie, możesz użyć reakcji i wydać jedną kość manewru, aby wykonać przeciw niemu jeden atak bronią wręcz. Jeśli trafisz, dodajesz wynik kości manewru do obrażeń.",
  "Right Tool for the Job": "Po godzinie pracy z narzędziami majsterkowicza możesz stworzyć jeden wybrany zestaw narzędzi rzemieślniczych. Gdy użyjesz tej zdolności ponownie, poprzednio stworzony zestaw znika.",
  "Roguish Archetype": "Wybrana specjalizacja określa dodatkowe zdolności Łotrzyka. Wszystkie konkretne efekty są opisane osobno w sekcji Specjalizacja.",
  "Sacred Oath": "Wybrana przysięga określa specjalizację Paladyna. Wszystkie konkretne efekty przysięgi są opisane osobno w sekcji Specjalizacja.",
  "Savage Attacks": "Gdy uzyskasz trafienie krytyczne atakiem bronią wręcz, rzucasz jedną dodatkową kością obrażeń broni i dodajesz ją do obrażeń krytycznych.",
  "Shape Self": "Jako akcję możesz zmienić część swojego wyglądu w granicach dozwolonych przez tę cechę. Zmiana jest fizyczna i trwa do chwili, gdy ją zakończysz albo użyjesz zdolności ponownie. Nie zmienia twoich statystyk, rozmiaru ani wyposażenia.",
  "Shapechanger": "Jako akcję możesz zmienić swój wygląd i głos, pozostając w tym samym podstawowym rozmiarze i zachowując statystyki. Wyposażenie nie zmienia się razem z tobą. Wracasz do prawdziwej postaci po śmierci albo gdy świadomie zakończysz przemianę.",
  "Slayer's Prey": "Jako akcję dodatkową wybierasz stworzenie w odległości do 60 stóp, które widzisz. Pierwszy raz w każdej swojej turze, gdy trafisz ten cel atakiem bronią, zadajesz mu dodatkowe 1k6 obrażeń. Efekt trwa do następnego odpoczynku albo do wybrania innego celu.",
  "Sorcerous Origin": "Źródło twojej wrodzonej mocy określa specjalizację Zaklinacza. Wszystkie konkretne zdolności źródła są opisane osobno w sekcji Specjalizacja.",
  "Specialized Design": "Otrzymujesz wskazane na karcie dodatkowe biegłości. Ich premie są już uwzględnione w tabeli umiejętności oraz sekcji narzędzi.",
  "Speech of Beast and Leaf": "Możesz przekazywać proste idee zwierzętom i roślinom. Rozumieją sens twojego komunikatu, ale sama ta cecha nie daje im zdolności odpowiadania pełnymi zdaniami ani wykonywania złożonych poleceń.",
  "Spider Climb": "Masz szybkość wspinaczki równą normalnej szybkości. Możesz poruszać się po pionowych powierzchniach i po suficie bez używania rąk, o ile nic szczególnego nie uniemożliwia przyczepienia się do powierzchni.",
  "Step of the Wind": "Wydajesz 1 punkt skupienia i jako akcję dodatkową wykonujesz Sprint albo Odskok. Do końca tej tury podwajasz także odległość, którą możesz pokonać skokiem.",
  "Stone's Endurance": "Gdy otrzymujesz obrażenia, możesz użyć reakcji i rzucić 1k12 + 3. Zmniejszasz otrzymane obrażenia o uzyskany wynik. Masz 3 użycia i odzyskujesz wszystkie po długim odpoczynku.",
  "Superior Darkvision": "Widzisz w ciemności do 120 stóp. W półmroku widzisz jak w jasnym świetle, a w ciemności jak w półmroku. W całkowitej ciemności rozróżniasz tylko odcienie szarości.",
  "Telepathic Speech": "Jako akcję dodatkową wybierasz stworzenie, które widzisz w odległości określonej przez twoją Charyzmę. Przez liczbę minut równą modyfikatorowi Charyzmy możesz telepatycznie porozumiewać się z nim, jeśli znacie wspólny język. Połączenie kończy się wcześniej, jeśli oddalicie się poza dozwolony zasięg.",
  "Thieves' Cant": "Znasz tajny kod przestępczego półświatka. Możesz ukrywać wiadomości w pozornie zwykłej rozmowie. Przekazanie takiej zakodowanej wiadomości trwa około cztery razy dłużej niż powiedzenie jej wprost. Znasz także typowe tajne znaki używane do oznaczania bezpiecznych miejsc, zagrożeń i kontaktów.",
  "Tool Proficiency": "Otrzymujesz biegłość w zestawie narzędzi wskazanym na karcie. Premia z biegłości obowiązuje we wszystkich testach wykonywanych przy użyciu tych narzędzi.",
  "Tools of the Trade": "Otrzymujesz wskazane na karcie biegłości w pancerzu i narzędziach. Działają stale i są już uwzględnione w sekcji Biegłości i informacje.",
  "Unarmored Movement": "Jeśli nie nosisz pancerza ani tarczy, twoja szybkość zwiększa się o 10 stóp. Premia jest już uwzględniona w wartości Szybkości na karcie.",
  "Unending Breath": "Nie musisz oddychać i możesz wstrzymywać oddech bez ograniczenia czasu, dopóki nie jesteś obezwładniony.",
  "Vampiric Bite": "Twój naturalny atak ugryzieniem zadaje obrażenia kłute zgodnie z wartością na karcie. W określonych warunkach możesz wykorzystać wynik obrażeń do odzyskania punktów wytrzymałości albo zwiększenia kolejnego testu lub rzutu ataku, zgodnie z limitem użyć tej cechy.",
  "Way of the Brush": "Masz biegłość w przyborach kaligraficznych. Gdy test bezpośrednio korzysta z tych narzędzi, dodajesz do niego premię z biegłości.",
  "Wild Shape Improvement": "Na 5. poziomie możesz przyjmować formy zwierząt o stopniu zagrożenia do 1/2. Możesz wybierać formy ze szybkością pływania, ale nadal nie możesz wybierać form mających szybkość lotu. Wszystkie pozostałe zasady przemiany pozostają bez zmian."
});

Object.assign(FEATS, {
  "Actor": { name: "Aktor", description: "Zwiększasz Charyzmę o 1. Masz przewagę w testach Oszustwa i Występów wykonywanych podczas udawania innej osoby. Po słuchaniu głosu stworzenia przez co najmniej minutę możesz naśladować jego mowę albo inne wydawane przez nie dźwięki; słuchacz może rozpoznać imitację dopiero po udanym teście Intuicji przeciw twojemu testowi Oszustwa." },
  "Elemental Adept (Cold)": { name: "Mistrz zimna", description: "Gdy używasz mocy zadającej obrażenia od zimna, ignorujesz odporność celu na obrażenia od zimna. Ponadto każdą kość obrażeń tej mocy, na której wypadnie 1, traktujesz jak wynik 2. Atut nie ignoruje niewrażliwości na zimno." },
  "Elemental Adept (Fire)": { name: "Mistrz ognia", description: "Gdy używasz mocy zadającej obrażenia od ognia, ignorujesz odporność celu na obrażenia od ognia. Ponadto każdą kość obrażeń tej mocy, na której wypadnie 1, traktujesz jak wynik 2. Atut nie ignoruje niewrażliwości na ogień." },
  "Elemental Adept (Lightning)": { name: "Mistrz elektryczności", description: "Gdy używasz mocy zadającej obrażenia od elektryczności, ignorujesz odporność celu na obrażenia od elektryczności. Ponadto każdą kość obrażeń tej mocy, na której wypadnie 1, traktujesz jak wynik 2. Atut nie ignoruje niewrażliwości na elektryczność." },
  "Grappler": { name: "Zapaśnik", description: "Masz przewagę w rzutach ataku przeciw stworzeniu, które aktualnie pochwyciłeś. Możesz użyć akcji, aby spróbować unieruchomić pochwycony cel; wykonujesz przeciwstawny test chwytu. Przy sukcesie zarówno ty, jak i cel stajecie się unieruchomieni do zakończenia chwytu." },
  "Gunner": { name: "Strzelec", description: "Zwiększasz Zręczność o 1. Masz biegłość w broni palnej, jeśli jest używana w grze. Ignorujesz właściwość ładowania broni palnej, a obecność wrogiego stworzenia do 5 stóp nie daje ci utrudnienia w atakach dystansowych." },
  "Mounted Combatant": { name: "Jeździec bojowy", description: "Gdy dosiadasz stworzenia, masz przewagę w atakach wręcz przeciw pieszym celom mniejszym od twojego wierzchowca. Możesz przekierować na siebie atak wymierzony w wierzchowca. Jeśli wierzchowiec wykonuje rzut obronny na Zręczność przeciw efektowi zadającemu połowę obrażeń przy sukcesie, przy sukcesie otrzymuje 0 obrażeń, a przy porażce połowę." },
  "Observant": { name: "Spostrzegawczy", description: "Zwiększasz Inteligencję albo Mądrość o 1. Jeśli widzisz usta mówiącego stworzenia i znasz jego język, potrafisz czytać z ruchu warg. Otrzymujesz także +5 do pasywnej Czujności i pasywnej Analizy; wartości na karcie powinny uwzględniać tę premię." },
  "Piercer": { name: "Specjalista obrażeń kłutych", description: "Zwiększasz Siłę albo Zręczność o 1. Raz na turę po zadaniu obrażeń kłutych atakiem możesz przerzucić jedną kość obrażeń i musisz użyć nowego wyniku. Przy trafieniu krytycznym zadającym obrażenia kłute rzucasz dodatkową kością obrażeń broni." },
  "Slasher": { name: "Specjalista obrażeń ciętych", description: "Zwiększasz Siłę albo Zręczność o 1. Raz na turę, gdy trafisz i zadasz obrażenia cięte, możesz zmniejszyć szybkość celu o 10 stóp do początku swojej następnej tury. Gdy uzyskasz trafienie krytyczne zadające obrażenia cięte, cel ma utrudnienie we wszystkich rzutach ataku do początku twojej następnej tury." },
  "Spell Sniper": { name: "Strzelec mocy", description: "Gdy używasz mocy wymagającej rzutu ataku, jej zasięg jest podwojony. Twoje dystansowe ataki mocą ignorują połowiczną i trzyczwarte osłonę. Poznajesz także jedną sztuczkę wymagającą rzutu ataku z jednej z dozwolonych list; karta powinna wskazywać wybraną sztuczkę." },
  "Tavern Brawler": { name: "Uliczny wojownik", description: "Zwiększasz Siłę albo Kondycję o 1. Masz biegłość w improwizowanej broni. Twój atak bez broni zadaje 1k4 obrażeń. Gdy w swojej turze trafisz stworzenie atakiem bez broni albo improwizowaną bronią, możesz użyć akcji dodatkowej, aby spróbować je pochwycić." }
});

Object.assign(SPELLS, {
  "Bane": { name: "Osłabienie", description: "Akcja, zasięg 30 stóp, koncentracja do 1 minuty. Wybierasz do trzech widocznych stworzeń. Każde wykonuje rzut obronny na Charyzmę. Przy porażce za każdym razem, gdy wykonuje rzut ataku albo rzut obronny, rzuca dodatkowe k4 i odejmuje wynik od swojego rzutu. Wyższa komórka pozwala objąć dodatkowy cel za każdy poziom powyżej pierwszego." },
  "Barkskin": { name: "Twarda skóra", description: "Akcja, dotyk, koncentracja do 1 godziny. Skóra chętnego celu twardnieje. Przez czas trwania jego KP nie może być niższa niż 16, niezależnie od noszonego pancerza i innych sposobów obliczania KP." },
  "Bless": { name: "Bojowe wsparcie", description: "Akcja, zasięg 30 stóp, koncentracja do 1 minuty. Wybierasz do trzech stworzeń. Za każdym razem, gdy cel wykonuje rzut ataku albo rzut obronny, dodaje 1k4 do wyniku. Wyższa komórka pozwala objąć dodatkowy cel za każdy poziom powyżej pierwszego." },
  "Catapult": { name: "Kinetyczny pocisk", description: "Akcja, zasięg 60 stóp. Wybierasz luźny przedmiot ważący od 1 do 5 funtów. Przedmiot leci po prostej do 90 stóp. Pierwsze stworzenie na drodze wykonuje rzut obronny na Zręczność. Przy porażce cel i przedmiot otrzymują po 3k8 obrażeń obuchowych. Wyższa komórka zwiększa maksymalną masę przedmiotu o 5 funtów i obrażenia o 1k8 za każdy poziom powyżej pierwszego." },
  "Chaos Bolt": { name: "Pocisk chaosu", description: "Akcja, zasięg 120 stóp. Wykonujesz dystansowy atak mocą. Przy trafieniu zadajesz 2k8 + 1k6 obrażeń. Typ obrażeń zależy od wyników k8. Jeśli na obu k8 wypadnie ten sam wynik, energia może przeskoczyć na drugi cel do 30 stóp od pierwszego; wykonujesz nowy rzut ataku i nie możesz trafić tej samej istoty ponownie w ramach tego użycia." },
  "Charm Person": { name: "Wpływ na umysł", description: "Akcja, zasięg 30 stóp, czas trwania 1 godzina. Humanoid wykonuje rzut obronny na Mądrość, z przewagą jeśli walczy z tobą lub twoimi sojusznikami. Przy porażce jest tobą zauroczony. Traktuje cię jak przyjaznego znajomego. Gdy efekt się skończy, wie, że został przez ciebie nadnaturalnie zmanipulowany." },
  "Chromatic Orb (Cold)": { name: "Kula lodu", description: "Akcja, zasięg 90 stóp. Wykonujesz dystansowy atak mocą. Przy trafieniu cel otrzymuje 3k8 obrażeń od zimna, plus 1k8 za każdy poziom komórki powyżej pierwszego." },
  "Command": { name: "Rozkaz", description: "Akcja, zasięg 60 stóp. Wypowiadasz jednowyrazowe polecenie do stworzenia, które cię rozumie. Cel wykonuje rzut obronny na Mądrość. Przy porażce w swojej następnej turze wykonuje rozkaz w możliwie bezpośredni sposób. Polecenie nie działa, jeśli jest oczywiście samobójcze lub bezpośrednio szkodliwe dla celu." },
  "Conjure Animals": { name: "Przywołanie zwierząt", description: "Akcja, zasięg 60 stóp, koncentracja do 1 godziny. Przywołujesz duchy przyjmujące postać zwierząt. Liczba i maksymalna siła stworzeń zależą od wybranego wariantu mocy. Przywołane istoty są przyjazne, mają własną inicjatywę i wykonują twoje słowne polecenia. Znikają po spadku do 0 punktów wytrzymałości albo po zakończeniu koncentracji." },
  "Dancing Lights": { name: "Tańczące światła", description: "Akcja, zasięg 120 stóp, koncentracja do 1 minuty. Tworzysz do czterech małych świateł. Każde emituje półmrok w promieniu 10 stóp. Jako akcję dodatkową możesz przesunąć światła do 60 stóp, ale każde musi pozostawać do 20 stóp od innego światła stworzonego tą mocą." },
  "Daylight": { name: "Jasność", description: "Akcja, zasięg 60 stóp, czas trwania 1 godzina. Punkt albo przedmiot zaczyna emitować jasne światło w promieniu 60 stóp i półmrok przez kolejne 60 stóp. Jeśli wybierzesz przedmiot trzymany przez niechętne stworzenie, musi ono nie zdać rzutu obronnego na Zręczność, aby efekt się udał." },
  "Disguise Self": { name: "Zmiana wyglądu", description: "Akcja, czas trwania 1 godzina. Tworzysz iluzoryczną zmianę własnego wyglądu, ubioru i wyposażenia. Możesz wyglądać nieco wyżej lub niżej, ale nie zmieniasz podstawowej budowy ciała. Fizyczny kontakt ujawnia iluzję. Stworzenie może przeznaczyć akcję na zbadanie wyglądu i wykonać test Analizy przeciw ST twoich mocy." },
  "Druidcraft": { name: "Drobny przejaw natury", description: "Akcja, zasięg 30 stóp. Tworzysz niewielki efekt związany z naturą: przewidujesz pogodę na najbliższą dobę, sprawiasz że kwiat rozkwita albo nasiono kiełkuje, tworzysz drobny nieszkodliwy efekt sensoryczny albo zapalasz lub gasisz mały płomień." },
  "Enhance Ability": { name: "Wzmocnienie możliwości", description: "Akcja, dotyk, koncentracja do 1 godziny. Wybierasz jedną z sześciu cech i nadajesz celowi odpowiadające jej wzmocnienie. Każdy wariant daje przewagę w testach danej cechy oraz dodatkowy efekt, na przykład tymczasowe punkty wytrzymałości, zwiększony udźwig albo zmniejszone obrażenia od upadku. Wyższa komórka pozwala objąć dodatkowy cel." },
  "Enlarge/Reduce": { name: "Zwiększenie lub zmniejszenie", description: "Akcja, zasięg 30 stóp, koncentracja do 1 minuty. Stworzenie lub przedmiot zwiększa albo zmniejsza rozmiar o jedną kategorię. Niechętne stworzenie wykonuje rzut obronny na Kondycję. Zwiększony cel ma przewagę w testach i rzutach obronnych na Siłę i zadaje dodatkowe 1k4 obrażeń bronią. Zmniejszony ma utrudnienie w takich testach i zadaje o 1k4 mniej obrażeń bronią." },
  "Entangle": { name: "Pnącza", description: "Akcja, zasięg 90 stóp, koncentracja do 1 minuty. Obszar kwadratu 20 na 20 stóp staje się trudnym terenem. Stworzenia znajdujące się w nim podczas tworzenia efektu wykonują rzut obronny na Siłę. Przy porażce zostają unieruchomione. Unieruchomione stworzenie może użyć akcji i wykonać test Siły przeciw ST twoich mocy, uwalniając się przy sukcesie." },
  "Feather Fall": { name: "Łagodne opadanie", description: "Reakcja, gdy ty albo stworzenie do 60 stóp zaczyna spadać. Wybierasz do pięciu spadających stworzeń. Przez maksymalnie 1 minutę ich szybkość spadania wynosi 60 stóp na rundę, a po bezpiecznym lądowaniu nie otrzymują obrażeń od upadku." },
  "Find Steed": { name: "Przywołanie wierzchowca", description: "10 minut użycia. Przywołujesz inteligentnego, lojalnego wierzchowca w wybranej postaci. Tworzy z tobą więź telepatyczną do 1 mili. Gdy dosiadasz go, moce o zasięgu na samego siebie mogą również obejmować wierzchowca. Jeśli spadnie do 0 punktów wytrzymałości albo go odprawisz, znika i może zostać przywołany ponownie kolejnym użyciem mocy." },
  "Fireball": { name: "Eksplozja energii", description: "Akcja, zasięg 150 stóp. W wybranym punkcie wybucha kula energii o promieniu 20 stóp. Każde stworzenie w obszarze wykonuje rzut obronny na Zręczność. Przy porażce otrzymuje 8k6 obrażeń od ognia, przy sukcesie połowę. Wyższa komórka dodaje 1k6 obrażeń za każdy poziom powyżej trzeciego." },
  "Flame Blade": { name: "Ogniste ostrze", description: "Akcja dodatkowa, koncentracja do 10 minut. Tworzysz w wolnej ręce płonące ostrze. Jako akcję możesz wykonać nim atak wręcz mocą; trafienie zadaje 3k6 obrażeń od ognia. Ostrze emituje jasne światło w promieniu 10 stóp i półmrok przez kolejne 10 stóp." },
  "Goodberry": { name: "Regeneracyjne kapsułki", description: "Akcja. Tworzysz 10 drobnych porcji energii lub pożywienia. Stworzenie może użyć akcji, aby zużyć jedną porcję, odzyskując 1 punkt wytrzymałości i otrzymując wystarczające odżywienie na jeden dzień. Niewykorzystane porcje znikają po 24 godzinach." },
  "Guidance": { name: "Wsparcie", description: "Akcja, dotyk, koncentracja do 1 minuty. Wybrane stworzenie może raz przed końcem efektu rzucić k4 i dodać wynik do jednego wybranego testu cechy. Może zdecydować się na użycie kości przed albo po rzucie k20, ale zanim prowadzący poda wynik testu." },
  "Gust of Wind": { name: "Potężny podmuch", description: "Akcja, koncentracja do 1 minuty. Tworzysz linię silnego wiatru długości 60 stóp i szerokości 10 stóp. Stworzenie rozpoczynające turę w linii wykonuje rzut obronny na Siłę; przy porażce zostaje odepchnięte o 15 stóp. Poruszanie się w stronę źródła wiatru kosztuje podwójny ruch. Jako akcję dodatkową możesz zmienić kierunek linii." },
  "Heroism": { name: "Niezłomność", description: "Akcja, dotyk, koncentracja do 1 minuty. Chętne stworzenie staje się odporne na przerażenie. Na początku każdej swojej tury otrzymuje tymczasowe punkty wytrzymałości równe modyfikatorowi twojej cechy magicznej. Po zakończeniu efektu pozostałe punkty tymczasowe znikają." },
  "Invisibility": { name: "Kamuflaż", description: "Akcja, dotyk, koncentracja do 1 godziny. Cel staje się niewidzialny wraz z noszonym i trzymanym wyposażeniem. Efekt kończy się wcześniej, gdy cel zaatakuje albo użyje mocy opartej na zaklęciu." },
  "Lesser Restoration": { name: "Pomniejsze odnowienie", description: "Akcja, dotyk. Kończysz jedną chorobę albo jeden z następujących stanów działających na cel: oślepienie, ogłuchnięcie, paraliż lub zatrucie." },
  "Magic Weapon": { name: "Wzmocnienie broni", description: "Akcja dodatkowa, dotyk, koncentracja do 1 godziny. Niemagiczna broń staje się magiczna i otrzymuje +1 do rzutów ataku i obrażeń. Przy komórce 4. poziomu premia rośnie do +2, a przy 6. poziomu do +3." },
  "Mending": { name: "Naprawa", description: "1 minuta użycia, dotyk. Naprawiasz pojedyncze pęknięcie albo rozdarcie w przedmiocie, nie większe niż 1 stopa w dowolnym wymiarze. Moc może fizycznie naprawić magiczny przedmiot lub konstrukt, ale nie przywraca utraconej magicznej funkcji." },
  "Mind Sliver": { name: "Odłamek umysłu", description: "Akcja, zasięg 60 stóp. Cel wykonuje rzut obronny na Inteligencję. Przy porażce na 5. poziomie otrzymuje 2k6 obrażeń psychicznych i musi odjąć 1k4 od następnego rzutu obronnego wykonanego przed końcem twojej następnej tury." },
  "Plant Growth": { name: "Przerost roślinności", description: "Akcja albo 8 godzin. Przy użyciu jako akcja wybierasz punkt w zasięgu 150 stóp; zwykłe rośliny w promieniu 100 stóp gęstnieją, a każdy 1 stopa ruchu przez obszar kosztuje 4 stopy ruchu. Możesz pozostawić dowolne fragmenty obszaru wolne. Przy użyciu przez 8 godzin wzbogacasz roślinność na dużym obszarze na rok." },
  "Produce Flame": { name: "Płomień w dłoni", description: "Akcja. W dłoni pojawia się płomień na maksymalnie 10 minut. Emituje jasne światło w promieniu 10 stóp i półmrok przez kolejne 10 stóp. Możesz zakończyć efekt, rzucając płomień w cel do 30 stóp; wykonujesz dystansowy atak mocą, a trafienie na 5. poziomie zadaje 2k8 obrażeń od ognia." },
  "Protection from Evil and Good": { name: "Ochrona przed istotami nadnaturalnymi", description: "Akcja, dotyk, koncentracja do 10 minut. Wybrane stworzenie jest chronione przed określonymi typami istot nadnaturalnych. Takie istoty mają utrudnienie w atakach przeciw celowi. Cel nie może zostać przez nie zauroczony, przerażony ani opętany; jeśli już jest pod takim efektem, ma przewagę w kolejnych rzutach obronnych wykonywanych, aby go zakończyć." },
  "Rime's Binding Ice": { name: "Lodowa fala", description: "Akcja. Stożek zimna długości 30 stóp. Każde stworzenie w obszarze wykonuje rzut obronny na Kondycję. Przy porażce otrzymuje 3k8 obrażeń od zimna i jego szybkość spada do 0 na 1 minutę. Przy sukcesie otrzymuje połowę obrażeń i nie traci szybkości. Unieruchomiony lodem cel albo inne stworzenie może użyć akcji, aby rozbić lód i zakończyć ograniczenie ruchu." },
  "Sacred Flame": { name: "Promień światła", description: "Akcja, zasięg 60 stóp. Cel wykonuje rzut obronny na Zręczność, przy którym nie korzysta z premii za osłonę. Przy porażce na 5. poziomie otrzymuje 2k8 obrażeń promienistych." },
  "Searing Smite": { name: "Płonące uderzenie", description: "Akcja dodatkowa, koncentracja do 1 minuty. Następne trafienie bronią wręcz w czasie trwania efektu zadaje dodatkowe 1k6 obrażeń od ognia i podpala cel. Na początku każdej swojej tury płonący cel wykonuje rzut obronny na Kondycję; przy porażce otrzymuje kolejne 1k6 obrażeń od ognia, przy sukcesie efekt się kończy. Cel lub inne stworzenie może użyć akcji, aby ugasić płomienie." },
  "Shatter": { name: "Roztrzaskanie", description: "Akcja, zasięg 60 stóp. W punkcie w zasięgu powstaje wybuch o promieniu 10 stóp. Każde stworzenie w obszarze wykonuje rzut obronny na Kondycję. Przy porażce otrzymuje 3k8 obrażeń od grzmotu, przy sukcesie połowę. Konstrukty i istoty z materiałów nieorganicznych mają utrudnienie w tym rzucie. Niemagiczne przedmioty w obszarze również otrzymują obrażenia." },
  "Shield of Faith": { name: "Tarcza wiary", description: "Akcja dodatkowa, zasięg 60 stóp, koncentracja do 10 minut. Wybrane stworzenie otrzymuje +2 do KP przez czas trwania efektu." },
  "Shocking Grasp": { name: "Elektryczny dotyk", description: "Akcja, dotyk. Wykonujesz atak mocą wręcz z przewagą, jeśli cel ma metalowy pancerz. Przy trafieniu na 5. poziomie zadajesz 2k8 obrażeń od elektryczności, a cel nie może wykonywać reakcji do początku swojej następnej tury." },
  "Silent Image": { name: "Cichy obraz", description: "Akcja, zasięg 60 stóp, koncentracja do 10 minut. Tworzysz obraz przedmiotu, stworzenia albo zjawiska mieszczący się w sześcianie o boku 15 stóp. Jako akcję możesz przesuwać obraz w zasięgu, dostosowując jego ruch. Fizyczny kontakt ujawnia iluzję. Stworzenie może przeznaczyć akcję na zbadanie efektu i wykonać test Analizy przeciw ST twoich mocy." },
  "Sleet Storm": { name: "Lodowa burza", description: "Akcja, zasięg 150 stóp, koncentracja do 1 minuty. W cylindrze o promieniu 40 stóp i wysokości 20 stóp pojawia się lodowy deszcz. Obszar jest mocno przesłonięty, otwarty ogień gaśnie, a ziemia staje się trudnym terenem. Stworzenie wchodzące w obszar albo rozpoczynające w nim turę wykonuje rzut obronny na Zręczność; przy porażce zostaje powalone. Stworzenie koncentrujące się na mocy wykonuje dodatkowy rzut obronny na Kondycję przeciw ST twoich mocy, aby utrzymać koncentrację." },
  "Snilloc's Snowball Swarm": { name: "Grad lodowych pocisków", description: "Akcja, zasięg 90 stóp. W punkcie w zasięgu eksplodują lodowe pociski w promieniu 5 stóp. Każde stworzenie w obszarze wykonuje rzut obronny na Zręczność. Przy porażce otrzymuje 3k6 obrażeń od zimna, przy sukcesie połowę. Wyższa komórka dodaje 1k6 obrażeń za każdy poziom powyżej drugiego." },
  "Speak with Animals": { name: "Rozmowa ze zwierzętami", description: "Akcja, czas trwania 10 minut. Możesz rozumieć i słownie komunikować się ze zwierzętami. Ich wiedza i inteligencja pozostają ograniczone przez naturę danego stworzenia, ale mogą przekazać informacje o niedawnych wydarzeniach, miejscach i zagrożeniach w swoim otoczeniu." },
  "Speak with Plants": { name: "Rozmowa z roślinami", description: "Akcja, promień 30 stóp, czas trwania 10 minut. Nadajesz roślinom ograniczoną świadomość i możliwość komunikacji. Mogą przekazywać informacje o istotach i zdarzeniach w okolicy. Możesz także sprawić, że zwykłe rośliny chwilowo ułatwią albo utrudnią poruszanie się przez obszar." },
  "Spider Climb": { name: "Chodzenie po ścianach", description: "Akcja, dotyk, koncentracja do 1 godziny. Chętne stworzenie może poruszać się w górę, w dół i po pionowych powierzchniach oraz suficie bez używania rąk. Otrzymuje szybkość wspinaczki równą swojej normalnej szybkości." },
  "Spike Growth": { name: "Kolczasty teren", description: "Akcja, zasięg 150 stóp, koncentracja do 10 minut. Obszar o promieniu 20 stóp staje się trudnym terenem i jest zakamuflowany tak, aby wyglądać naturalnie. Za każde 5 stóp ruchu przez obszar stworzenie otrzymuje 2k4 obrażeń kłutych. Stworzenie, które nie widziało tworzenia efektu, może potrzebować testu Czujności, aby rozpoznać zagrożenie przed wejściem." },
  "Spiritual Weapon": { name: "Duchowa broń", description: "Akcja dodatkowa, zasięg 60 stóp, czas trwania 1 minuta, bez koncentracji. Tworzysz widmową broń i natychmiast możesz wykonać nią atak mocą wręcz przeciw celowi do 5 stóp od broni. Trafienie zadaje 1k8 + modyfikator twojej cechy magicznej obrażeń od energii. W kolejnych turach możesz akcją dodatkową przesunąć broń do 20 stóp i zaatakować ponownie." },
  "Suggestion": { name: "Sugestia", description: "Akcja, zasięg 30 stóp, koncentracja do 8 godzin. Formułujesz rozsądnie brzmiące polecenie dla stworzenia, które cię słyszy i rozumie. Cel wykonuje rzut obronny na Mądrość. Przy porażce postępuje zgodnie z sugestią najlepiej jak potrafi. Efekt kończy się po wykonaniu zadania albo wcześniej, jeśli ty lub twoi sojusznicy zranicie cel." },
  "Tasha's Mind Whip": { name: "Bicz umysłu", description: "Akcja, zasięg 90 stóp. Cel wykonuje rzut obronny na Inteligencję. Przy porażce otrzymuje 3k6 obrażeń psychicznych i do końca swojej następnej tury nie może wykonywać reakcji. W swojej następnej turze może wykonać tylko jedną z trzech rzeczy: ruch, akcję albo akcję dodatkową. Przy sukcesie otrzymuje połowę obrażeń i nie cierpi pozostałych efektów." },
  "Thorn Whip": { name: "Energetyczny bicz", description: "Akcja, zasięg 30 stóp. Wykonujesz atak mocą wręcz przeciw stworzeniu w zasięgu. Przy trafieniu na 5. poziomie zadajesz 2k6 obrażeń kłutych i, jeśli cel jest Duży lub mniejszy, możesz przyciągnąć go do siebie o maksymalnie 10 stóp." },
  "Thunderous Smite": { name: "Uderzenie falą", description: "Akcja dodatkowa, koncentracja do 1 minuty. Następne trafienie bronią wręcz w czasie trwania efektu zadaje dodatkowe 2k6 obrażeń od grzmotu. Jeśli cel jest Duży lub mniejszy, wykonuje rzut obronny na Siłę. Przy porażce zostaje odepchnięty o 10 stóp i powalony." },
  "Thunderwave": { name: "Fala uderzeniowa", description: "Akcja. Sześcian o boku 15 stóp wychodzący od ciebie zostaje objęty falą energii. Każde stworzenie w obszarze wykonuje rzut obronny na Kondycję. Przy porażce otrzymuje 2k8 obrażeń od grzmotu i zostaje odepchnięte o 10 stóp. Przy sukcesie otrzymuje połowę obrażeń i nie zostaje odepchnięte. Niezabezpieczone przedmioty również są odsuwane." },
  "Vortex Warp": { name: "Przemieszczenie przestrzenne", description: "Akcja, zasięg 90 stóp. Wybierasz stworzenie, które widzisz. Chętny cel może zrezygnować z rzutu; niechętny wykonuje rzut obronny na Kondycję. Przy porażce teleportujesz go na wolne pole, które widzisz w odpowiednim zasięgu od siebie. Nie możesz umieścić celu w powietrzu ani na powierzchni, która nie może go utrzymać." },
  "Web": { name: "Sieć obezwładniająca", description: "Akcja, zasięg 60 stóp, koncentracja do 1 godziny. Tworzysz sześcian lepkiej sieci o boku 20 stóp. Obszar jest trudnym terenem i lekko przesłonięty. Stworzenie rozpoczynające turę w sieci albo wchodzące do niej wykonuje rzut obronny na Zręczność; przy porażce zostaje unieruchomione. Może użyć akcji i wykonać test Siły przeciw ST twoich mocy, aby się uwolnić. Sieć jest łatwopalna." },
  "Wrathful Smite": { name: "Uderzenie grozy", description: "Akcja dodatkowa, koncentracja do 1 minuty. Następne trafienie bronią wręcz zadaje dodatkowe 1k6 obrażeń psychicznych. Cel wykonuje rzut obronny na Mądrość. Przy porażce jest tobą przerażony do końca efektu. Przerażony cel może użyć akcji i wykonać test Mądrości przeciw ST twoich mocy, kończąc efekt przy sukcesie." },
  "Zephyr Strike": { name: "Błyskawiczny atak", description: "Akcja dodatkowa, koncentracja do 1 minuty. Przez czas trwania twoje poruszanie się nie prowokuje ataków okazyjnych. Raz przed zakończeniem efektu możesz dać sobie przewagę w jednym ataku bronią. Jeśli ten atak trafi, zadaje dodatkowe 1k8 obrażeń od energii, a twoja szybkość zwiększa się o 30 stóp do końca tej tury." }
});
